update biz_order set order_status = #{orderStatus}, pay_status = #{payStatus},
    refund_status = #{refundStatus}, cancel_time = #{cancelTime}, cancel_reason = #{cancelReason}
where id = #{id} and order_status = 1 and pay_status = 1 and refund_status = 0

update biz_order set order_status = #{orderStatus}, pay_status = #{payStatus},
    cancel_time = #{cancelTime}, cancel_reason = #{cancelReason}
where id = #{id} and order_status = 0 and pay_status = 0

update biz_order
set order_status = 2, make_start_time = #{makeStartTime}, update_time = #{makeStartTime}
where id = #{id}
  and shop_id = #{shopId}
  and order_status = 1
  and pay_status = 1

update biz_order
set order_status = 3, complete_make_time = #{completeMakeTime}, update_time = #{completeMakeTime}
where id = #{id}
  and shop_id = #{shopId}
  and order_status = 2
  and pay_status = 1

update biz_order
set order_status = 4, verify_time = #{verifyTime}, update_time = #{verifyTime}
where id = #{id}
  and shop_id = #{shopId}
  and order_status = 3
  and pay_status = 1
